def minPath(grid, k):
    if not grid or not grid[0]:
        return []
    N = len(grid)
    visited = {}
    heap = []
    for i in range(N):
        for j in range(N):
            seq = [grid[i][j]]
            steps_left = k - 1
            heapq.heappush(heap, (seq, (i, j), steps_left))
