        seq, (i, j), steps_left = heapq.heappop(heap)
        if steps_left == 0:
            return seq
        for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N:
                new_seq = seq + [grid[ni][nj]]
                new_steps = steps_left - 1
                key = (ni, nj, new_steps)
                if key not in visited or new_seq < visited[key]:
                    visited[key] = new_seq
                    heapq.heappush(heap, (new_seq, (ni, nj), new_steps))
